{
  "name": "@dluck/opencode-learn-english",
  "version": "0.1.2",
  "description": "Non-intrusive opencode plugin that helps Chinese-speaking developers improve English while coding",
  "type": "module",
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "exports": {
    ".": {
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --target node --external @opencode-ai/plugin",
    "prepublishOnly": "bun run build",
    "test": "vitest run",
    "test:watch": "vitest"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "english-learning",
    "esl"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Dluckxx/opencode-learn-english-plugin.git"
  },
  "publishConfig": {
    "access": "public"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.3.2",
    "@types/bun": "latest",
    "@types/node": "^25.6.0",
    "typescript": "^5.8.3",
    "vitest": "^3.1.1"
  }
}
